<template>
  <main class="min-h-screen space-y-5 bg-white p-6">
    <header class="flex flex-wrap items-center justify-between gap-3"><div><h1 class="text-2xl font-bold text-slate-900">Lignes budgétaires</h1><p class="mt-1 text-sm text-slate-500">Plafonds planifiés et révisés, issus des budgets de votre organisation.</p></div><button class="rounded-lg bg-bleu-nuit px-4 py-2 text-sm font-semibold text-white hover:opacity-90" @click="openForm">Ajouter une ligne</button></header>
    <p v-if="error" class="rounded-lg bg-red-50 p-3 text-sm text-red-700">{{ error }}</p>
    <div class="overflow-x-auto rounded-xl border border-slate-200"><table class="w-full text-left text-sm"><thead class="bg-slate-50 text-xs uppercase text-slate-500"><tr><th class="p-3">Ligne</th><th class="p-3">Budget / projet</th><th class="p-3">Catégorie</th><th class="p-3 text-right">Prévu</th><th class="p-3 text-right">Révisé</th></tr></thead><tbody><tr v-for="line in rows" :key="line.id" class="border-t border-slate-100"><td class="p-3 font-medium text-slate-800">{{ line.libelle }}</td><td class="p-3 text-slate-600">{{ line.budget_projet || line.budget_nom || line.budget }}</td><td class="p-3 text-slate-600">{{ line.categorie || '—' }}</td><td class="p-3 text-right">{{ money(line.montant_prevu) }} FCFA</td><td class="p-3 text-right">{{ line.montant_revise == null ? '—' : `${money(line.montant_revise)} FCFA` }}</td></tr><tr v-if="!loading && !rows.length"><td colspan="5" class="p-8 text-center text-slate-500">Aucune ligne budgétaire enregistrée.</td></tr></tbody></table></div>
    <div class="flex items-center justify-between text-sm text-slate-500"><span>{{ total }} ligne(s)</span><div class="flex gap-2"><button :disabled="!previous || loading" class="rounded border px-3 py-1 disabled:opacity-40" @click="load(previous)">Précédent</button><button :disabled="!next || loading" class="rounded border px-3 py-1 disabled:opacity-40" @click="load(next)">Suivant</button></div></div>
    <div v-if="formOpen" class="fixed inset-0 z-50 flex items-center justify-center bg-black/40 p-4" @click.self="formOpen = false"><form class="w-full max-w-lg space-y-4 rounded-xl bg-white p-6 shadow-xl" @submit.prevent="save"><div class="flex items-center justify-between"><h2 class="text-lg font-bold text-slate-900">Nouvelle ligne budgétaire</h2><button type="button" class="text-xl text-slate-500" aria-label="Fermer" @click="formOpen = false">×</button></div><label class="block text-sm font-medium text-slate-700">Budget<select v-model="form.budget" required class="mt-1 w-full rounded-lg border border-slate-200 p-2"><option value="">Sélectionner un budget</option><option v-for="b in budgets" :key="b.id" :value="b.id">{{ b.projet_nom }} — {{ money(b.montant) }} FCFA</option></select></label><label class="block text-sm font-medium text-slate-700">Libellé<input v-model.trim="form.libelle" required maxlength="255" class="mt-1 w-full rounded-lg border border-slate-200 p-2" placeholder="Ex. Achat de fournitures" /></label><label class="block text-sm font-medium text-slate-700">Cat?gorie<select v-model="form.categorie" class="mt-1 w-full rounded-lg border border-slate-200 p-2"><option value="">S?lectionner une cat?gorie</option><option v-for="category in financeCategories" :key="category" :value="category">{{ category }}</option></select></label><label class="block text-sm font-medium text-slate-700">Montant prévu (FCFA)<input v-model.number="form.montant_prevu" required type="number" min="1" step="0.01" class="mt-1 w-full rounded-lg border border-slate-200 p-2" /></label><label class="block text-sm font-medium text-slate-700">Observation<textarea v-model.trim="form.observation" rows="2" class="mt-1 w-full rounded-lg border border-slate-200 p-2" /></label><p v-if="formError" class="text-sm text-red-600">{{ formError }}</p><div class="flex justify-end gap-2"><button type="button" class="rounded-lg border px-4 py-2 text-sm" @click="formOpen = false">Annuler</button><button :disabled="saving" class="rounded-lg bg-bleu-nuit px-4 py-2 text-sm font-semibold text-white disabled:opacity-60">{{ saving ? 'Enregistrement…' : 'Enregistrer' }}</button></div></form></div>
  </main>
</template>

<script setup>
import { onMounted, reactive, ref } from 'vue'
import { useRoute } from 'vue-router'
import api from '@/services/api.js'
import { FINANCE_CATEGORIES } from '@/modules/finance/constants/categories.js'
import { financeService } from '@/modules/finance/services/financeService.js'
const route = useRoute()
const financeCategories = FINANCE_CATEGORIES
const rows = ref([]), budgets = ref([]), loading = ref(false), error = ref(''), next = ref(null), previous = ref(null), total = ref(0)
const formOpen = ref(false), saving = ref(false), formError = ref('')
const form = reactive({ budget: '', libelle: '', categorie: '', montant_prevu: '', observation: '' })
const money = (value) => Number(value || 0).toLocaleString('fr-FR')
async function load(url) {
  loading.value = true; error.value = ''
  try { const response = url ? await api.get(url) : await financeService.fetchBudgetLines(); const data = response.data; rows.value = Array.isArray(data) ? data : data.results || []; next.value = Array.isArray(data) ? null : data.next; previous.value = Array.isArray(data) ? null : data.previous; total.value = Array.isArray(data) ? rows.value.length : data.count || rows.value.length }
  catch { error.value = 'Impossible de charger les lignes budgétaires.' } finally { loading.value = false }
}
function openForm() { form.budget = String(route.query.budget || ''); form.libelle = ''; form.categorie = ''; form.montant_prevu = ''; form.observation = ''; formError.value = ''; formOpen.value = true }
async function save() { saving.value = true; formError.value = ''; try { await financeService.createBudgetLine({ ...form, montant_prevu: Number(form.montant_prevu) }); formOpen.value = false; await load() } catch (e) { formError.value = e?.response?.data?.detail || Object.values(e?.response?.data || {}).flat().join(' ') || 'Impossible de créer la ligne.' } finally { saving.value = false } }
onMounted(async () => { try { const { data } = await financeService.fetchBudgets(); budgets.value = Array.isArray(data) ? data : data.results || [] } catch { /* list view reports data loading failures */ } await load(); if (route.query.budget) openForm() })
</script>
